  lines.append('|'+v['subset']+'/'+str(v['seed'])+'|'+str(v['train_original_scenes'])+' / '+f"{v['raw_valid_labels']:,}"+'|'+str(v['scene_exposure_min'])+'–'+str(v['scene_exposure_max'])+'|'+'|'.join(cells)+'|')
